import{_ as l,b as a,c as e,I as i}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"喵！开站大吉——猫窝开张日志","description":"柳卿烟的猫窝正式开张——一个二次元高中生的博客新起点","frontmatter":{"title":"喵！开站大吉——猫窝开张日志","date":"2026-09-15T00:00:00.000Z","tags":["建站","日常"],"cover":"/LQY/images/cover-shizuku.webp","head":[["meta",{"name":"description","content":"柳卿烟的猫窝正式开张——一个二次元高中生的博客新起点"}],["meta",{"name":"keywords","content":"建站, 博客, 开站, 二次元"}]]},"headers":[],"relativePath":"posts/hello-world.md","filePath":"posts/hello-world.md"}'),o={name:"posts/hello-world.md"};function s(r,t,n,c,d,p){return a(),e("div",null,[...t[0]||(t[0]=[i('<p>一个高中生的博客，第三次开张了。这次是猫窝主题，门口蹲着一只会跟着你视线转的 Live2D 猫娘。</p><hr><h2 id="首先是个自我介绍" tabindex="-1">首先是个自我介绍 <a class="header-anchor" href="#首先是个自我介绍" aria-label="Permalink to &quot;首先是个自我介绍&quot;">​</a></h2><p>这里是柳卿烟，一名普通（自称）的高中二年级学生。白天在教室里和函数搏斗，晚上在小屏幕前过自己的第二人生——<strong>追番、QQ飞车、网页游戏考古，以及给猫羽雫打 call</strong>。</p><p>这个猫窝大概会记录这些：</p><ul><li>🐾 猫羽雫相关的收集汇报与安利（单推人的自我修养）</li><li>🚗 QQ飞车的段位沉浮录与技术碎碎念</li><li>🕹️ 网页游戏黄金时代的考古笔记（4399 学家上线）</li><li>📺 追番扫雷报告（季节性爆发）</li><li>🎧 通学路上的歌单分享</li><li>📚 月考生存实录（主要是吐槽）</li><li>🔧 折腾博客本身的记录</li></ul><h2 id="这个站有什么" tabindex="-1">这个站有什么 <a class="header-anchor" href="#这个站有什么" aria-label="Permalink to &quot;这个站有什么&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">功能清单</p><ul><li><strong>搜索</strong>：右上角放大镜，全站文章秒搜</li><li><strong>夜间模式</strong>：右上角开关，切换后看板娘会换睡衣哦（晚自习偷偷看也不刺眼，不要学）</li><li><strong>看板娘</strong>：左下角的猫娘 Shizuku，视线跟着鼠标走，点她有惊喜</li><li><strong>猫爪特效</strong>：随便点点屏幕，爪印啪叽啪叽的，很解压</li><li><strong>评论</strong>：每篇文章底部，GitHub 登录就能发言</li><li><strong>BGM</strong>：右上角音乐按钮，8-bit 小曲， Made with Python</li></ul></div><h2 id="关于更新频率" tabindex="-1">关于更新频率 <a class="header-anchor" href="#关于更新频率" aria-label="Permalink to &quot;关于更新频率&quot;">​</a></h2><details><summary>点开查看一份非常诚实的承诺</summary><p>理想状态：每周一更。 现实状态：月考周停更，假期爆更，开学吃灰，周末看情况复活。 总之，随缘但不断更（大概）。</p></details><div class="warning custom-block"><p class="custom-block-title">免责声明</p><p>本站所有内容都是一个高中生的个人视角，观点主观、口癖严重、语法偶有翻车。如果和你意见不合，欢迎评论区分对错（划掉）交流。</p></div><p>那么，欢迎来到我的猫窝。上课铃响了，先溜了——喵。</p>',12)])])}const m=l(o,[["render",s]]);export{u as __pageData,m as default};
